-- SAH-2 · platform.sales_enquiry : a public "Contact sales" or "Book a Demo" request from the home page.
-- Belongs to no clinic: it is written by a visitor who has no account. No row level security.
-- The mobile number is personal data: never log it.
-- Row ids are generated by the application (or by the column default); the app role cannot read this table.
create table if not exists platform.sales_enquiry (
  id          uuid primary key default gen_random_uuid(),
  name        text not null
              constraint ck_sales_enquiry_name check (char_length(btrim(name)) between 1 and 120),
  clinic_city text
              constraint ck_sales_enquiry_clinic_city check (char_length(clinic_city) <= 200),
  mobile      varchar(10) not null
              constraint ck_sales_enquiry_mobile check (mobile ~ '^[6-9][0-9]{9}$'),
  best_time   text
              constraint ck_sales_enquiry_best_time check (best_time in ('MORNING', 'AFTERNOON', 'AFTER_OPD')),
  source      text not null
              constraint ck_sales_enquiry_source check (source in ('CONTACT_SALES', 'BOOK_DEMO')),
  created_at  timestamptz not null default now()
);

-- Insert only. The schema default privileges give sahaj_app four commands, so remove them first.
revoke all on platform.sales_enquiry from sahaj_app;
revoke all on platform.sales_enquiry from public;
grant insert on platform.sales_enquiry to sahaj_app;
